import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long target = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        final long MOD = 1000000007L;
        long total = 0;
        for (long x : a) total += x;
        if (Math.abs(target) > total || (total + target) % 2 != 0) {
            System.out.println(0);
        } else {
            int need = (int) ((total + target) / 2);
            long[] ways = new long[need + 1];
            ways[0] = 1;
            for (int k = 0; k < n; k++) {
                int x = (int) a[k];
                for (int s = need; s >= x; s--) {
                    ways[s] = (ways[s] + ways[s - x]) % MOD;
                }
            }
            System.out.println(ways[need]);
        }
    }
}
